{
  "skills": [
    {
      "skill_id": "chalcogenide_pnictide_gap_transfer",
      "rules": [
        {
          "rule_id": "chalcogenide_anion_positive",
          "conditions": {
            "anion_family": "chalcogenide"
          },
          "weight": 0.72,
          "rationale": "Source dielectric transfer gave chalcogenide a strong positive effect; chalcogenide anions open valence-band maxima, widening gaps."
        },
        {
          "rule_id": "pnictide_anion_positive",
          "conditions": {
            "anion_family": "pnictide"
          },
          "weight": 0.81,
          "rationale": "Strongest shared prior among the top anion families; pnictide p-states span the gap, widening experimental band gaps."
        },
        {
          "rule_id": "halide_anion_negative",
          "conditions": {
            "anion_family": "halide"
          },
          "weight": -0.68,
          "rationale": "Halide reversed weight in source; high electronegativity and gap-narrowing carrier levels suppress experimental gaps."
        },
        {
          "rule_id": "metalloid_dominant_positive",
          "conditions": {
            "dominant_family": "metalloid"
          },
          "weight": 0.75,
          "rationale": "High source support with large max effect; metalloid lattices favor wide-gap covalent bonding motifs."
        }
      ],
      "ridge": 1.6,
      "prior_scale": 0.35,
      "semantic_mass_start": 0.42,
      "semantic_mass_end": 0.18,
      "ucb_weight": 0.58,
      "gp_beta_start": 2.2,
      "gp_beta_end": 1.0,
      "gp_xi": 0.012,
      "confidence": 0.66,
      "hypothesis": "Chalcogenide and pnictide anions plus metalloid dominance transfer a positive gap signal from refractive-index physics. Fails when strong anion polarizability or transition-metal d-states collapse the gap."
    },
    {
      "skill_id": "counter_high_z_lanthanide_gap_reversal",
      "rules": [
        {
          "rule_id": "mean_z_very_high_downweighted",
          "conditions": {
            "mean_atomic_number_bin": "mean_z_very_high"
          },
          "weight": -0.35,
          "rationale": "Reverses the uncertain source prior; heavy-element f and d manifolds often pin or close experimental gaps."
        },
        {
          "rule_id": "lanthanide_dominant_negative",
          "conditions": {
            "dominant_family": "lanthanide"
          },
          "weight": -0.55,
          "rationale": "Weak source support for lanthanide; localized f-states introduce mid-gap levels and reduce measured gaps."
        },
        {
          "rule_id": "has_lanthanide_flag_negative",
          "conditions": {
            "lanthanide_flag": "has_lanthanide"
          },
          "weight": -0.42,
          "rationale": "Source lanthanide effect was near zero with low confidence, so counts as a gap-narrowing inhibitor."
        },
        {
          "rule_id": "balanced_stoichiometry_positive",
          "conditions": {
            "max_element_fraction_bin": "balanced"
          },
          "weight": 0.48,
          "rationale": "Balanced compositions in source had positive effects; they support ordered wide-gap stoichiometric compounds."
        }
      ],
      "ridge": 2.4,
      "prior_scale": 0.22,
      "semantic_mass_start": 0.30,
      "semantic_mass_end": 0.08,
      "ucb_weight": 0.45,
      "gp_beta_start": 1.8,
      "gp_beta_end": 0.9,
      "gp_xi": 0.02,
      "confidence": 0.58,
      "hypothesis": "High mean atomic number and lanthanide presence downweight the source's weak positive prior, treating f and d occupancy as a gap-narrowing penalty. Might fail if the target's light-metal oxides dominate."
    }
  ],
  "selected_skill_id": "chalcogenide_pnictide_gap_transfer",
  "lesson": "Anion-family transfer from dielectric source carries the strongest, most interpretable gap signal; mean-Z and lanthanide relations are weak and warrant counter-weighting rather than blind adoption.",
  "revision_summary": "Retained the positive anion and metalloid transfer signal, downweighted low-confidence lanthanide and very-high-Z relations, and selected the chalcogenide/pnictide skill for deployment with a moderate ridge to control variance."
}

